"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";
import {
	formatHslTriplet,
	hexToHslTriplet,
	hslTripletToHex,
	parseHslTriplet,
} from "../../lib/color.js";
import { Input } from "../../primitives/input/input.js";
import { Label } from "../../primitives/label/label.js";
import { Slider } from "../../primitives/slider/slider.js";
import { Popover, PopoverContent, PopoverTrigger } from "../popover/popover.js";

/** Tolerance for treating a float as integer-valued (handles arithmetic drift in HSL roundtrips). */
const INTEGER_EPSILON = 1e-6;

const looksInteger = (n: number) => Math.abs(n - Math.round(n)) < INTEGER_EPSILON;

/** Props for the ColorPicker component. */
export interface ColorPickerProps {
	/**
	 * Current color as an HSL triplet string (`"<H> <S>% <L>%"`, e.g. `"240 5.9% 10%"`).
	 * Match the format used by `@hex-core/tokens`; round-trip safe.
	 */
	value: string;
	/**
	 * Called with the next HSL triplet whenever the user drags a slider or commits a valid hex value.
	 * Not called for invalid hex input — the picker keeps the prior value until the input parses cleanly.
	 */
	onChange: (value: string) => void;
	/**
	 * Disable interaction. Native `disabled` attribute is set on the trigger so the
	 * popover doesn't open via mouse or keyboard activation. Tab focus still lands
	 * on the trigger per browser defaults; if you want to fully remove it from the
	 * tab order, wrap in a parent that handles `tabIndex` accordingly.
	 */
	disabled?: boolean;
	/** Accessible name for the trigger button (defaults to "Pick color"). */
	"aria-label"?: string;
	/** Additional class names merged onto the trigger. */
	className?: string;
}

/**
 * HSL-native color picker. Edits an HSL triplet directly via three sliders
 * (H/S/L), with a hex input as a display adapter.
 *
 * Round-trip safe: triplet → hex → triplet preserves the slider state because
 * sliders are the source of truth and hex updates them only when valid.
 *
 * @param props - Controlled component; `value` and `onChange` are required.
 * @returns A trigger button that opens a popover with H/S/L sliders + hex input.
 * @example
 * ```tsx
 * const [color, setColor] = React.useState("240 5.9% 10%");
 * <ColorPicker value={color} onChange={setColor} aria-label="Primary color" />
 * ```
 */
function ColorPicker({
	value,
	onChange,
	disabled,
	"aria-label": ariaLabel = "Pick color",
	className,
}: ColorPickerProps) {
	// Memoize so the slider-row callbacks below are stable across renders with
	// the same `value`; downstream `Slider`s avoid spurious re-mounts.
	const hsl = React.useMemo(() => parseHslTriplet(value), [value]);
	const hex = React.useMemo(() => hslTripletToHex(value), [value]);

	const update = React.useCallback(
		(patch: Partial<typeof hsl>) => {
			onChange(formatHslTriplet({ ...hsl, ...patch }));
		},
		[hsl, onChange],
	);

	// Hex input is locally controlled so the user can type intermediate states
	// (e.g. "#1a") without committing. Sync the buffer to the canonical hex
	// whenever the input is NOT focused — typing into a focused input must not
	// be clobbered by a parent re-render reflecting our own `onChange`.
	const hexInputRef = React.useRef<HTMLInputElement>(null);
	const [hexBuffer, setHexBuffer] = React.useState(hex);
	React.useEffect(() => {
		if (
			typeof document === "undefined" ||
			document.activeElement !== hexInputRef.current
		) {
			setHexBuffer(hex);
		}
	}, [hex]);

	const handleHexChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		const next = e.target.value;
		setHexBuffer(next);
		const triplet = hexToHslTriplet(next);
		if (triplet !== null) onChange(triplet);
	};

	const hexId = React.useId();

	return (
		<Popover>
			<PopoverTrigger asChild>
				<button
					type="button"
					disabled={disabled}
					aria-label={ariaLabel}
					className={cn(
						"inline-flex h-9 items-center gap-2 rounded-md border border-input bg-background px-3 text-sm shadow-sm",
						"transition-all duration-[var(--duration-normal,200ms)] ease-out",
						"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
						"hover:shadow-md disabled:pointer-events-none disabled:opacity-50",
						className,
					)}
				>
					<span
						aria-hidden="true"
						className="h-5 w-5 rounded-sm border border-border"
						style={{ backgroundColor: `hsl(${value})` }}
					/>
					<span className="font-mono text-xs uppercase">{hex}</span>
				</button>
			</PopoverTrigger>
			<PopoverContent className="w-72 p-4" align="start">
				<div className="space-y-4">
					<SliderRow
						label="Hue"
						suffix="°"
						value={hsl.h}
						max={360}
						step={1}
						onChange={(h) => update({ h })}
					/>
					<SliderRow
						label="Saturation"
						suffix="%"
						value={hsl.s}
						max={100}
						step={0.1}
						onChange={(s) => update({ s })}
					/>
					<SliderRow
						label="Lightness"
						suffix="%"
						value={hsl.l}
						max={100}
						step={0.1}
						onChange={(l) => update({ l })}
					/>
					<div className="flex items-end gap-2">
						<div className="flex-1 space-y-1">
							<Label htmlFor={hexId} className="text-xs">
								Hex
							</Label>
							<Input
								id={hexId}
								ref={hexInputRef}
								value={hexBuffer}
								onChange={handleHexChange}
								className="font-mono text-xs uppercase"
								spellCheck={false}
								autoComplete="off"
							/>
						</div>
						<span
							aria-hidden="true"
							className="h-9 w-9 shrink-0 rounded-md border border-border"
							style={{ backgroundColor: `hsl(${value})` }}
						/>
					</div>
				</div>
			</PopoverContent>
		</Popover>
	);
}

interface SliderRowProps {
	label: string;
	suffix: string;
	value: number;
	max: number;
	step: number;
	onChange: (next: number) => void;
}

/**
 * One labeled slider row inside the ColorPicker popover. Internal helper —
 * not exported.
 * @param props - Slider config + value-change callback.
 */
function SliderRow({ label, suffix, value, max, step, onChange }: SliderRowProps) {
	const display = looksInteger(value) ? `${Math.round(value)}` : value.toFixed(1);
	return (
		<div className="space-y-1.5">
			<div className="flex items-center justify-between">
				<Label className="text-xs">{label}</Label>
				<span className="font-mono text-xs tabular-nums text-muted-foreground">
					{display}
					{suffix}
				</span>
			</div>
			<Slider
				value={[value]}
				min={0}
				max={max}
				step={step}
				aria-label={label}
				onValueChange={(values) => onChange(values[0] ?? 0)}
			/>
		</div>
	);
}

export { ColorPicker };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

